"""3.5 채권 가격 분해와 취약 구간, 3.6 시장 상태와 상대 스프레드."""
import json
import numpy as np, pandas as pd

pc = lambda x, d=1: f"{x * 100:.{d}f}%".replace("-", "−"); f2 = lambda x: f"{x:.2f}".replace("-", "−"); f3 = lambda x: f"{x:.3f}".replace("-", "−")
bp = lambda x: f"{x:+.0f}".replace("-", "−"); bpa = lambda x: f"{x:.0f}"
num = lambda x: f"{int(x):,}"
GR = "ABCDEFG"


def cellname(r):
    g = (lambda k: r[k]) if isinstance(r, (dict, pd.Series)) else (lambda k: getattr(r, k))
    return f"{int(g('만기'))}개월 {g('등급')}등급"


def build(P):
    T = P.tables
    BW = pd.read_csv(T / "채권2_워터폴.csv"); BM = pd.read_csv(T / "채권2_모형대조.csv"); BV = pd.read_csv(T / "채권2_취약구간.csv"); BS = pd.read_csv(T / "채권2_충격.csv")
    BC = pd.read_csv(T / "채권2_조건칸.csv"); BJ = json.load(open(T / "채권2_요약.json")); POOL = pd.read_csv(T / "채권_풀.csv"); PSA = pd.read_csv(T / "채권_PSA.csv"); DUR = pd.read_csv(T / "채권_듀레이션.csv")
    SS = pd.read_csv(T / "교수_H_상태공간.csv"); SSJ = json.load(open(T / "교수_H_상태공간_요약.json")); LS = pd.read_csv(T / "교수_C_롱숏.csv"); OLS = pd.read_csv(T / "교수_B_OLS.csv").set_index("모형")
    MKT = pd.read_csv(T / "채권_시장회귀.csv"); LAD = pd.read_csv(T / "채권_사다리.csv"); BJ0 = json.load(open(T / "채권_요약.json"))
    h = []
    n_ok = int((BM.오차_bp.abs() <= 30).sum()); n_cell = len(BM); ap, aps, tot = BJ["FOC승인칸"], BJ["스트레스후_승인칸"], BJ["전체칸"]
    sh = BS.pivot_table(index=["만기", "등급"], columns="충격", values="수익률변화_bp"); SK = {k: [c for c in sh.columns if c.startswith(k)][0] for k in ("부도율", "손실률", "회수 지연", "조기상환 ×1.5", "조기상환 ×0.5", "신용 스트레스")}
    addon = BS[BS.충격.str.startswith("신용 스트레스")].set_index(["만기", "등급"]).방어쿠폰가산_bp
    ret = lambda t, g: float(BW[(BW.만기 == t) & (BW.등급 == g)].보존율.iloc[0])
    bm = lambda t, g, c: float(BM[(BM.만기 == t) & (BM.등급 == g)][c].iloc[0])

    # ---------------- 3.5
    h.append(P.h3("3.5 채권 가격 분해와 취약 구간"))
    h.append(P.p("먼저 풀 단위에서 대출이 채권처럼 움직이는지를 보았다. [[t:mk_pool]]에서 승인한 대출 풀의 36개월 약정 스프레드는 "
                 f"{pc(POOL[(POOL.풀 == 'V3') & (POOL.만기 == 36)].약정스프레드.iloc[0])}이고 실현 스프레드는 {pc(POOL[(POOL.풀 == 'V3') & (POOL.만기 == 36)].실현스프레드_전.iloc[0])}로, 약정의 {pc(POOL[(POOL.풀 == 'V3') & (POOL.만기 == 36)].보존율.iloc[0], 0)}가 남았다. "
                 f"승인하지 않은 풀은 보존율이 {pc(POOL[(POOL.풀 == 'V3_거절') & (POOL.만기 == 36)].보존율.iloc[0], 0)}에 그쳐, 같은 약정 조건에서도 승인 규칙이 실현 수익을 크게 갈랐다. 실현 가중평균만기(WAL)는 36개월 풀에서 "
                 f"{POOL[(POOL.풀 == 'V3') & (POOL.만기 == 36)].WAL.iloc[0]:.2f}년으로 계약만기 3년보다 훨씬 짧아, 조기상환이 현금흐름을 앞당기는 효과가 크다."))
    rows = []
    for g, lab in (("V3", "승인"), ("V3_거절", "미승인"), ("ALL", "전체")):
        for t in (36, 60):
            r = POOL[(POOL.풀 == g) & (POOL.만기 == t)]
            if len(r): r = r.iloc[0]; rows.append([f"{lab} {t}개월", num(r.n), pc(r.약정금리), pc(r.풀수익률_전), pc(r.약정스프레드), pc(r.실현스프레드_전), pc(r.보존율, 0), f"{r.WAL:.2f}", pc(r.CNL)])
    h.append(P.tab("mk_pool", "승인·미승인 풀의 약정 대비 실현 수익률과 스프레드", ["풀", "건수", "약정금리", "실현 수익률(수수료 전)", "약정 스프레드", "실현 스프레드", "보존율", "WAL(년)", "누적 순손실률"], rows, widths=["16%", "10%", "10%", "14%", "12%", "12%", "9%", "8%", "9%"]))
    psa = PSA.set_index("집단"); d_est = DUR[(DUR.풀 == "V3") & (DUR.증권 == "자동이전증권")].set_index("경우")
    h.append(P.p(f"조기상환과 부도의 속도는 PSA 기준으로 36개월 승인 풀이 {psa.loc['36_승인', 'PSA속도']:.1f}배, 평균 연 조기상환율(CPR)이 {pc(psa.loc['36_승인', '평균CPR'])}였다. 이 속도를 반영한 유효 듀레이션은 자동이전증권 기준 "
                 f"{d_est.iloc[0].ED:.2f}년, 볼록성은 {d_est.iloc[0].ECV:.1f}로 계산되었다. 금리가 내릴 때 조기상환이 늘어난다는 가정을 넣지 않은 경우(고정)에는 듀레이션이 {d_est.iloc[1].ED:.2f}년이어서, 조기상환 반응이 듀레이션을 줄이는 방향으로 작용한다."))
    h.append(P.h4("(1) 기대 현금흐름 모형의 재현"))
    h.append(P.p(f"만기와 등급으로 나눈 14개 칸마다 나이별 조기상환율(SMM)과 부도율(MDR), 손실률로 기대 현금흐름을 만들고 만기수익률(YTM)을 구해 실현 수익률과 맞춰 보았다. 14개 칸 중 {n_ok}개에서 오차의 절댓값이 30bp 이하였고, 중앙 오차는 {BJ['모형오차_bp_중앙절대']:.0f}bp, 최대 오차는 "
                 f"{BJ['모형오차_bp_최대절대']:.0f}bp({cellname(BM.loc[BM.오차_bp.abs().idxmax()])})였다([[t:mk_fit]]). 모형과 실현을 같은 자료에서 맞춘 것이므로 이 결과는 표본 안의 재현이며 표본 밖 검증은 아니다. 오차는 36개월 저등급에서 커서 모형이 실현보다 높게 나왔는데, 칸 안의 위험 이질성이 평균 위험률로 만든 현금흐름을 낙관적으로 만들었을 가능성이 있다(추정)."))
    h.append(P.tab("mk_fit", "칸별 모형 만기수익률과 실현 수익률(수수료 전, 연율)", ["칸", "약정금리", "모형 YTM", "실현", "오차(bp)", "공정 쿠폰", "위험 프리미엄", "부도 제거 시 변화(bp)", "조기상환 제거 시(bp)"],
                   [[cellname(r), pc(r.약정금리), pc(r.모형_YTM, 2), pc(r.실현_수수료전, 2), bp(r.오차_bp), pc(r.공정쿠폰, 2), pc(r.위험프리미엄, 2), bp(r.부도제거시_bp), bp(r.조기상환제거시_bp)] for r in BM.itertuples()],
                   widths=["13%", "9%", "10%", "9%", "9%", "11%", "12%", "14%", "13%"]))
    h.append(P.p("공정 쿠폰은 기대 현금흐름을 무위험 수익률로 할인했을 때 가격이 1이 되는 쿠폰이며, 약정금리에서 이를 뺀 위험 프리미엄은 모형 YTM에서 무위험 수익률을 뺀 값과 칸별로 ±7bp 이내에서 같았다. 따라서 위험 프리미엄은 이 연구의 목표 변수인 초과수익의 기댓값을 채권의 언어로 옮긴 것으로 읽을 수 있다. 한편 조기상환을 없애면 YTM이 오히려 낮아졌는데, 액면가 상환은 이익도 손실도 아니고 부도에 노출되는 잔액과 기간을 줄이기 때문일 것으로 보인다(추정)."))
    h.append(P.h4("(2) 스프레드 워터폴"))
    h.append(P.p(f"약정 스프레드가 실현 스프레드로 줄어드는 과정을 이자와 원금만 받은 경우의 내부수익률, 회수금을 더한 경우, 수수료를 뺀 경우의 순서로 나누었다([[t:mk_waterfall]], [[f:mk_waterfallfig]]). 14개 칸 모두에서 부도 손실의 절댓값이 회수금과 수수료의 절댓값 합보다 컸다. "
                 f"36개월 A등급은 약정 스프레드의 {pc(ret(36, 'A'), 0)}가 남았으나 G등급은 {pc(ret(36, 'G'), 0)}로 원금조차 돌려받지 못했다. 회수금은 부도 잔액의 약 12%만 메워, 저등급으로 갈수록 약정 스프레드의 증가분이 부도 손실의 증가분에 못 미쳤다."))
    h.append(P.tab("mk_waterfall", "약정 스프레드에서 실현 스프레드까지의 분해(연율, %p)", ["칸", "약정 스프레드", "부도 손실", "회수금", "수수료", "실현 스프레드", "보존율"],
                   [[cellname(r), f2(r.약정스프레드 * 100), f2(r.손실효과 * 100), "+" + f2(r.회수효과 * 100), f2(r.수수료효과 * 100), f2(r.실현스프레드 * 100), pc(r.보존율, 0)] for r in BW.itertuples()], widths=["16%", "16%", "14%", "12%", "12%", "17%", "13%"]))
    h.append(P.fig("mk_waterfallfig", "채권2_워터폴.png", "약정 스프레드에서 부도 손실, 회수금, 수수료를 거쳐 실현 스프레드에 이르는 과정. 36개월 G등급은 실현 스프레드가 음수이다.", h="58mm"))
    h.append(P.h4("(3) 시기별 현금흐름과 취약 구간"))
    vrows = []
    for t_, g_ in ((36, "A"), (36, "D"), (36, "G"), (60, "A"), (60, "D"), (60, "G")):
        v = BV[(BV.만기 == t_) & (BV.등급 == g_)]; tot_ = v[v.나이구간 == "전체"].iloc[0]; part = v[v.나이구간 != "전체"].set_index("나이구간")
        vrows.append([f"{t_}개월 {g_}등급"] + [pc(part.순손실비중.get(b, np.nan), 0) if b in part.index else "—" for b in ("1~6", "7~12", "13~24", "25~36", "37~60")] + [f"{int(tot_.회수월)}개월" if tot_.회수월 == tot_.회수월 else "회수 못함", pc(tot_.누적순손실률), f2(tot_.이자_대_손실)])
    h.append(P.p("[[f:mk_timeline]]은 대출액 1당 월별 이자, 원금, 회수금, 순손실을 나이별로 그린 것이다. 순손실은 부도 후 6개월에야 확정되므로 처음 몇 달에는 거의 없고, 13~36개월 구간에 몰렸다([[t:mk_loss]]). 36개월 A등급은 전체 순손실의 "
                 f"{pc(float(BV[(BV.만기 == 36) & (BV.등급 == 'A') & (BV.나이구간.isin(['13~24', '25~36']))].순손실비중.sum()), 0)}가 이 구간에서 생겼다. 이자 대 순손실 비율이 1에 가까운 저등급에서는 받은 이자가 손실을 간신히 메우는 구조이며, 36개월 G등급은 누적 현금이 끝내 원금에 닿지 못했다."))
    h.append(P.fig("mk_timeline", "채권2_시기별현금흐름.png", "대출액 1당 월별 현금흐름(이자, 원금, 회수금, 순손실)과 누적 순손실. 만기 36·60개월, 등급 A·D·G.", h="82mm"))
    h.append(P.tab("mk_loss", "순손실이 생기는 나이 구간(전체 순손실 중 비중)과 원금 회수 시점", ["칸", "1~6개월", "7~12개월", "13~24개월", "25~36개월", "37~60개월", "원금 회수월", "누적 순손실률", "이자 ÷ 순손실"], vrows,
                   widths=["13%", "10%", "10%", "11%", "11%", "11%", "12%", "11%", "11%"]))
    h.append(P.h4("(4) 충격 민감도"))
    h.append(P.p(f"부도율 ×1.25, 손실률 +10%p, 회수 지연 6개월, 조기상환 ×1.5와 ×0.5를 각각 주었을 때의 YTM 변화가 [[t:mk_shock]]이다. 가장 민감한 요인은 부도율로, 36개월 A등급에서 {bp(sh.loc[(36, 'A'), SK['부도율']])}bp, G등급에서 {bp(sh.loc[(36, 'G'), SK['부도율']])}bp였다. "
                 f"회수 지연과 조기상환의 영향은 수 bp에서 수십 bp에 그쳤다. 신용 요인 세 가지를 한꺼번에 준 스트레스에서 충격 전 YTM을 지키려면 쿠폰을 36개월 A등급 {bpa(addon.loc[(36, 'A')])}bp부터 G등급 {bpa(addon.loc[(36, 'G')])}bp까지 올려야 했다. "
                 "이 가산량에는 쿠폰이 높아질 때 위험한 차입자가 몰리는 역선택이 반영되어 있지 않다."))
    h.append(P.tab("mk_shock", "충격별 만기수익률 변화(bp)와 방어 쿠폰 가산", ["칸", "부도율 ×1.25", "손실률 +10%p", "회수 지연 +6개월", "조기상환 ×1.5", "조기상환 ×0.5", "신용 스트레스(동시)", "방어 쿠폰 가산(bp)"],
                   [[cellname(dict(만기=k[0], 등급=k[1]))] + [bp(sh.loc[k, SK[c]]) for c in ("부도율", "손실률", "회수 지연", "조기상환 ×1.5", "조기상환 ×0.5", "신용 스트레스")] + [bpa(addon.loc[k])] for k in sh.index],
                   widths=["13%", "11%", "11%", "12%", "11%", "11%", "17%", "14%"]))
    h.append(P.h4("(5) 조건별 위험 대비 수익"))
    crow = []
    for (t_, g_), gg in BC.groupby(["T", "grade"]):
        gg = gg.set_index("dti3"); crow.append([f"{t_}개월 {g_}등급", num(gg.건수.sum())] + [f2(gg.loc[k, "Sharpe"]) for k in ("낮음", "중간", "높음")] + [f"{int(gg.FOC승인.sum())}/3", f"{int(gg.스트레스후_FOC승인.sum())}/3", bpa(gg.스트레스_bp.iloc[0])])
    mdti = BC.pivot_table(index=["T", "grade"], columns="dti3", values="Sharpe"); n_dti = int((mdti["낮음"] > mdti["높음"]).sum())
    h.append(P.p(f"만기, 등급, 상환부담(DTI) 3분위로 나눈 {tot}개 칸에서 칸 평균 초과수익을 칸 수익의 표준편차로 나눈 Sharpe를 계산하였다([[t:mk_cells]]). 같은 만기와 등급 안에서는 DTI가 낮은 칸의 Sharpe가 높은 칸보다 높은 경우가 {len(mdti)}개 중 {n_dti}개였다. "
                 f"1계조건 점수가 양인 칸은 {ap}개로 모두 A·B등급이었고, 신용 스트레스를 IRR 기준 충격에서 초과수익 척도로 환산해 반영하면 {aps}개가 남았다(환산계수 36개월 {BJ['환산계수']['36']:.2f}, 60개월 {BJ['환산계수']['60']:.2f}). "
                 "따라서 스트레스에서 승인 칸이 크게 줄어든다는 가설은 이 자료에서 지지되지 않았다. 칸 사이의 상관은 0으로 두었고 이 진단은 학습 자료 안의 결과이다."))
    h.append(P.tab("mk_cells", f"만기·등급·DTI 칸의 위험 대비 초과수익과 1계조건 승인 칸 수(DTI 경계 {BJ['dti_분위경계'][0]:.1f}, {BJ['dti_분위경계'][1]:.1f})", ["칸", "건수", "Sharpe(DTI 낮음)", "중간", "높음", "승인(3칸 중)", "스트레스 후 승인", "스트레스 ΔYTM(bp)"], crow,
                   widths=["14%", "11%", "13%", "9%", "9%", "14%", "15%", "15%"]))

    # ---------------- 3.6
    h.append(P.h3("3.6 시장 상태와 상대 스프레드"))
    MZ = OLS.loc["MZ 불편성 z = α + β·μ̂"]
    h.append(P.p(f"채권의 관점에서 보면 시장 전체의 스프레드 수준을 맞히는 일은 어렵고, 같은 시점 안에서 대출 사이의 상대적 위치를 맞히는 일이 현실적이다. 먼저 상대 스프레드의 예측이 불편한지를 보았다. 발급월 군집 표준오차를 쓴 회귀에서 부도확률과 스프레드를 통제하고 본 연구의 예측 초과수익을 넣었을 때 계수는 "
                 f"{OLS.loc['M4 +우리 예측', 'b_mu']:.2f}(t = {OLS.loc['M4 +우리 예측', 't_mu']:.1f})였다. " + f"예측이 불편하다면 실현 초과수익을 예측에 회귀한 기울기가 1이고 절편이 0이어야 한다(Mincer–Zarnowitz 검정). 추정한 기울기는 {MZ.b_mu:.3f}(표준오차 {MZ.se_mu:.3f})로 1과 구분되지 않았으나 절편은 0이 아니어서 예측이 평균적으로 보수적이었다."))
    h.append(P.p("판별력은 10분위 롱숏으로도 확인했다. 발급월 안에서 예측 점수로 10분위를 나누어 1분위를 사고 10분위를 파는 가상 포트폴리오를 만들면, 최종 모형은 "
                 f"월 평균 {LS.iloc[0].롱숏_평균:.1f}%p(Newey–West t = {LS.iloc[0].NW_t:.1f})를 얻었고 {pc(LS.iloc[0].양수_월비율, 0)}의 달에서 양(+)이었다. 부도확률 순위는 {LS.iloc[1].롱숏_평균:.1f}%p, 세부등급 순위는 {LS.iloc[2].롱숏_평균:.1f}%p에 그쳤다([[t:mk_longshort]])."))
    h.append(P.tab("mk_longshort", "발급월별 10분위 롱숏(1분위 매수, 10분위 매도)", ["순위", "개월", "롱숏 평균(%p)", "Newey–West t", "양(+)인 달", "D1 평균", "D10 평균", "단조성(Spearman)"],
                   [[r.순위, int(r.개월), f2(r.롱숏_평균), f"{r.NW_t:.1f}", pc(r.양수_월비율, 0), f2(r.D1_평균), f2(r.D10_평균), f2(r.단조성_Spearman)] for r in LS.itertuples()], widths=["18%", "8%", "13%", "13%", "11%", "12%", "12%", "13%"]))
    reg = MKT.set_index("회귀")
    h.append(P.p(f"시장 스프레드와의 관계는 약했다. 대출 약정 스프레드의 월 변화를 Baa 회사채 스프레드 변화에 회귀한 계수는 {MKT.iloc[0].계수:.2f}(t = {MKT.iloc[0].t:.1f})로 유의하지 않았고, 30년 모기지 스프레드에는 {MKT.iloc[1].계수:.2f}(t = {MKT.iloc[1].t:.1f})였다. 발급월 Baa 스프레드로 실현 스프레드를 예측하는 회귀의 설명력은 "
                 f"{pc(MKT.iloc[2].R2, 2)}에 불과해, 시장 스프레드는 대출의 실현 스프레드를 예측하지 못했다."))
    h.append(P.h4("상태공간 모형과 마르코프 전환"))
    aic = SSJ["aic"]
    h.append(P.p(f"신용 환경이 천천히 움직이는 상태를 갖는지 보기 위해 36개월 대출의 발급월 평균 초과수익({SSJ['월수']}개월)에 세 모형을 적합하였다. 상수 평균 모형, 상태가 확률보행을 따르는 지역 수준(local level) 모형, 두 국면의 마르코프 전환 모형이다. "
                 f"지역 수준 모형의 AIC가 {aic['(b) 지역 수준 상태공간']:.1f}로 가장 낮았고 마르코프 {aic['(c) 2국면 마르코프 전환']:.1f}, 상수 {aic['(a) 상수 평균']:.1f}가 뒤를 이었다([[t:mk_state]]). 표준화 잔차의 자기상관은 유의하지 않았다(Ljung–Box p = {SSJ['ljungbox_p']:.2f}). "
                 f"신호 대 잡음비는 {SSJ['signal_noise']:.2f}로, 월 변동의 절반 이상이 서서히 움직이는 수준 변화에서 왔다. 반면 최근 30개월의 한 걸음 앞 예측 RMSE는 지역 수준 {SSJ['rmse']['지역 수준']:.3f}, 임의보행 {SSJ['rmse']['임의보행']:.3f}으로 거의 같아, 수준은 지속적이지만 앞으로의 값을 더 잘 맞히지는 못하였다."))
    h.append(P.tab("mk_state", "발급월 평균 초과수익에 대한 세 모형의 적합도", ["모형", "모수 수", "로그우도", "AIC", "한 걸음 예측 RMSE(최근 30개월)"],
                   [[r.모형, int(r.모수), f"{r.로그우도:.1f}".replace("-", "−"), (f"{r.AIC:.1f}"), ("—" if r._7 != r._7 else f"{r._7:.3f}")] for r in SS.rename(columns={"한걸음예측_RMSE(최근30개월)": "_7"}).itertuples()], widths=["30%", "12%", "16%", "14%", "28%"]))
    h.append(P.fig("mk_statefig", "lab5_상태공간.png", "월별 평균 초과수익과 평활 상태(지역 수준 모형), 악화 국면 확률(마르코프 전환). 두 방법이 같은 시기를 악화로 가리킨다.", h="58mm"))
    h.append(P.p(f"평활된 수준과 마르코프의 악화 확률의 상관은 {SSJ['상관_수준_대_악화확률']:.2f}로, 두 방법은 수준이 낮은 같은 시기를 악화로 보았다. 이 결과는 승인 규칙을 바꾸는 신호가 아니라 최근 수준을 모니터링해 수익 추정과 위험회피 계수를 다시 맞출 시점을 알리는 진단으로 쓰는 것이 적절하다."))
    return "".join(h)
